if __name__ == "__main__":
    import json, os
    for cc in sys.argv[1:]:
        rows = globals()[cc.lower().replace("do", "do_") if False else cc.lower()]()
        p = f"/workspace/world_courts/data/{cc.lower()}/{cc.lower()}_judges.jsonl"; old = []
        if os.path.exists(p): old = [json.loads(l) for l in open(p)]
        seen = {r["judge_id"]: r for r in old}
        for r in rows: seen[r["judge_id"]] = r
        with open(p, "w") as f:
            for r in seen.values(): f.write(json.dumps(r, ensure_ascii=False) + "\n")
        print(cc, len(rows), len(seen))
